def _layoff_days_of(row, date_val):
    """前走日から今回までの日数。取れなければ None。
    危険人気馬の休養ソフト理由(半年休み明け/中9週+/短距離休み明け)用。"""
    pr = row.get('PastRuns') if hasattr(row, 'get') else None
    if not (isinstance(pr, list) and pr and date_val):
        return None
    try:
        from datetime import datetime as _dt_lay
        pd8 = (str(pr[0].get('Date', '') or '')
               .replace('.', '').replace('-', '').replace('/', '')[:8])
        dv = str(date_val).replace('.', '').replace('-', '').replace('/', '')[:8]
        if len(pd8) != 8 or not pd8.isdigit() or len(dv) != 8 or not dv.isdigit():
            return None
        days = (_dt_lay.strptime(dv, '%Y%m%d') - _dt_lay.strptime(pd8, '%Y%m%d')).days
        return days if days >= 0 else None
    except (TypeError, ValueError, AttributeError):
        return None


def _prev_chaku_of(row):
    """出走表の1行から前走着順(int)を返す。取れなければ None。
    軸信頼度の『前走1着=勝ち上がり直後は過剰人気』減点用(axis_selector.PREV_WIN_DEMERIT)。"""
    pr = row.get('PastRuns') if hasattr(row, 'get') else None
    if isinstance(pr, list) and pr:
        try:
            return int(pr[0].get('Rank'))
        except (TypeError, ValueError, AttributeError):
            return None
    return None


def _pos_ratio_of(row, field_size):
    """平均通過位置の『比率』(0-1・小さいほど前)を返す。取れなければ None。
    軸信頼度の『本物の先行(<0.28)は過剰人気』減点用(axis_selector.FRONT_DEMERIT)。"""
    try:
        n = int(field_size)
        ap = float(row.get('AvgPosition'))
        if n <= 0 or ap <= 0:
            return None
        return min(1.0, ap / n)
    except (TypeError, ValueError, AttributeError):
        return None


def get_netkeiba_domain(race_id):
    """Detects the appropriate netkeiba domain based on race_id."""
    try:
        pid = int(str(race_id)[4:6])
        if pid > 10:
            return "nar.netkeiba.com"
    except:
        pass
    return "race.netkeiba.com"

# === 🔬 スコアリングシグナル: 当日JRAレースをスキャンしてJ◎/T●を取得 ===
_SIGNAL_CACHE_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                 'data', 'signal_cache')


def _signal_cache_path(race_date_str, is_nar):
    """🔬当日シグナルの日付キャッシュのパス。JRA/NARで別ファイル。"""
    return os.path.join(_SIGNAL_CACHE_DIR,
                        f"{race_date_str}_{'nar' if is_nar else 'jra'}.json")


def _load_daily_signals_all(race_date_str, is_nar):
    """日付キャッシュ全体 {race_id: {umaban(str): {...}}} を読む。無ければNone。"""
    import json as _json
    try:
        with open(_signal_cache_path(race_date_str, is_nar), 'r', encoding='utf-8') as f:
            return _json.load(f)
    except Exception:
        return None


def _save_daily_signals_all(race_date_str, is_nar, allmap):
    import json as _json
    try:
        os.makedirs(_SIGNAL_CACHE_DIR, exist_ok=True)
        with open(_signal_cache_path(race_date_str, is_nar), 'w', encoding='utf-8') as f:
            _json.dump(allmap, f, ensure_ascii=False)
    except Exception:
        pass


def _fetch_daily_signals(rid: str, race_date_str: str):
    """当日の全レース(対象がJRAならJRA中央01-10/NARなら地方>10)をスキャンし
    シグナルmap {umaban: {marks,j_dc,t_bullet}} を返す。scrape_raceはrace_idで
    実データ取得(get_race_dataがNAR自動判定)する為、南関等の地方でも機能する。
    race_date_str: YYYYMMDD 形式の実際のカレンダー日付"""
    try:
        from core.scraper import get_race_list_for_date
        from scripts.race_position_scanner import run_scan_with_signals
        race_list = get_race_list_for_date(race_date_str)
        if not race_list:
            return {}
        # 対象レースと同じ"世界"(JRA中央 or NAR地方)の当日レースをスキャン。
        # 地方はvenue>10。スキャナはrace_idで実データ取得(get_race_dataがNAR自動判定)する為、
        # URLドメインは無関係だが、明示的に正しいドメインを付す(nar/race)。
        _tgt_vc = rid[4:6] if len(str(rid)) == 12 else '99'
        _tgt_is_nar = _tgt_vc.isdigit() and int(_tgt_vc) > 10
        _dom = "nar.netkeiba.com" if _tgt_is_nar else "race.netkeiba.com"
        urls = []
        for r in race_list:
            r_id = r['race_id'] if isinstance(r, dict) else str(r)
            vc = r_id[4:6] if len(r_id) == 12 else '99'
            if not vc.isdigit():
                continue
            _v = int(vc)
            _in_scope = (_v > 10) if _tgt_is_nar else (1 <= _v <= 10)
            if _in_scope:
                urls.append(f"https://{_dom}/race/shutuba.html?race_id={r_id}")
        if not urls:
            return {}
        df_sig, _, _ = run_scan_with_signals(urls=urls, entity='both', min_patterns=1, output_csv=None)
        if df_sig is None or df_sig.empty:
            return {}
        # 当日全レース分をまとめて日付キャッシュへ保存する。
        # 以前は全レースを走査しておきながら対象1レース分だけ取り出して捨てていたため、
        # 別レースを開くたびに同じ重いスキャンをやり直していた(セッション内キャッシュも
        # race_idキーで共有されない)。一括解析ではレースごとに新しいブラウザ
        # セッションになるので、ディスクに置かないと36レース分スキャンし直しになる。
        _all = {}
        if 'race_id' in df_sig.columns:
            for _, row in df_sig.iterrows():
                _rk = str(row.get('race_id', ''))
                if not _rk:
                    continue
                try:
                    _uma = int(row.get('horse_number', 0))
                except (TypeError, ValueError):
                    continue
                _all.setdefault(_rk, {})[str(_uma)] = {
                    'marks':    str(row.get('special_marks', '')),
                    'j_dc':     bool(row.get('jockey_dc_flag', False)),
                    't_bullet': bool(row.get('trainer_bullet_flag', False)),
                    'score':    float(row.get('score', 0)),
                }
        if _all:
            _save_daily_signals_all(race_date_str, _tgt_is_nar, _all)
        return {int(k): v for k, v in (_all.get(rid) or {}).items()}
    except Exception as _e:
        import logging
        logging.getLogger(__name__).warning(f"[Signal] fetch failed: {_e}")
        return {}

def render_session_status(key_prefix=""):
    """Renders session status and login buttons for Umanity and KeibaLab."""
    import os
    from datetime import datetime
    
    col1, col2 = st.columns(2)
    
    # Define absolute paths for session files
    base_dir = os.path.dirname(os.path.abspath(__file__))
    session_umanity = os.path.join(base_dir, "auth_session.json")
    session_labo = os.path.join(base_dir, "labo_session.json")
    
    # --- Umanity ---
    with col1:
        st.markdown("**🔑 認証 (Umanity / U指数)**")
        if os.path.exists(session_umanity):
            mtime = os.path.getmtime(session_umanity)
            dt_mtime = datetime.fromtimestamp(mtime).strftime('%Y-%m-%d %H:%M:%S')
            st.success(f"✅ 保存済み ({dt_mtime})")
