                        def color_density_penalty(s):
                            """密集ペナルティ: 密集=赤文字、余裕=青文字"""
                            colors = []
                            for v in s:
                                sv = str(v)
                                if '密集' in sv:  colors.append("color:#E63946; font-weight:bold")
